// Validate + normalise an incoming level save.
// Keeps all shape-checking here so the HTTP nodes stay dumb.

const cfg = $('Repo Config').first().json;
const wh = $('Webhook').first().json;

function parseMaybe(v) {
  if (v == null) return null;
  if (typeof v === 'string') {
    const s = v.trim();
    if (!s) return null;
    try { return JSON.parse(s); } catch { return null; }
  }
  if (typeof v === 'object') return v;
  return null;
}

const root = wh || {};
const body = parseMaybe(root.body) || parseMaybe(root.data) || root.body || root;

// --- optional shared secret (same header the meme flow uses) --------------
const secret = String(cfg.webhookSecret || '').trim();
if (secret) {
  const headers = root.headers || {};
  const got = String(headers['x-coinduel-secret'] || headers['X-Coinduel-Secret'] || body.secret || '');
  if (got !== secret) {
    return [{ json: { ok: false, statusCode: 401, error: 'Unauthorized (bad secret)' } }];
  }
}

// --- level id ---------------------------------------------------------
const levelId = Number(body.levelId);
if (!Number.isFinite(levelId) || levelId < 1 || levelId > 99999) {
  return [{ json: { ok: false, statusCode: 400, error: 'levelId must be a positive integer' } }];
}

// --- level body -------------------------------------------------------
let level = parseMaybe(body.levelJson) || parseMaybe(body.level);
if (!level) {
  return [{ json: { ok: false, statusCode: 400, error: 'levelJson required (object or JSON string)' } }];
}

// Shape gate: a level has numeric id/width/height, a wall, and a coins array.
// A ModConfig bundle also has `level` but carries schemaVersion — reject it so
// the editor cannot accidentally clobber a stage with a whole mod.
if (level.schemaVersion != null) {
  return [{ json: { ok: false, statusCode: 400, error: 'levelJson looks like a ModConfig (schemaVersion present), not a level' } }];
}
if (typeof level.width !== 'number' || typeof level.height !== 'number') {
  return [{ json: { ok: false, statusCode: 400, error: 'levelJson missing numeric width/height' } }];
}
if (!Array.isArray(level.coins)) {
  return [{ json: { ok: false, statusCode: 400, error: 'levelJson missing coins[]' } }];
}
if (!level.wall || typeof level.wall.thickness !== 'number') {
  level.wall = { thickness: 64 };
}
level.id = levelId;

const path = cfg.levelsPath + '/' + levelId + '.json';
const bodyText = JSON.stringify(level, null, 4) + '\n';

return [{
  json: {
    ok: true,
    levelId,
    owner: cfg.owner,
    repo: cfg.repo,
    branch: cfg.branch,
    path,
    contentBase64: Buffer.from(bodyText, 'utf8').toString('base64'),
    coins: level.coins.length,
    commitMessage: 'editor: save level ' + levelId + ' (' + level.coins.length + ' coins)',
  },
}];

// Merge the validation payload with the sha of any existing file.
// 404 means "new level" — the PUT works without a sha then.

const base = $('Validate Level').first().json;
const res = $input.first().json || {};
const status = Number(res.statusCode || 0);

let sha = null;
if (status === 200 && res.sha) {
  sha = res.sha;
} else if (status === 404) {
  sha = null;
} else if (status !== 200 && status !== 404) {
  return [{ json: {
    ok: false,
    statusCode: 502,
    error: 'GitHub GET failed (' + status + '): ' + String((res && res.message) || 'no message'),
  } }];
}

return [{ json: Object.assign({}, base, { sha }) }];

// Turn the GitHub PUT response into the shape the editor expects.
const put = $input.first().json || {};
const base = $('Merge SHA').first().json;
const status = Number(put.statusCode || 0);

if (status === 200 || status === 201) {
  const commit = put && put.commit && put.commit.sha ? put.commit.sha : '';
  return [{ json: {
    ok: true,
    statusCode: 200,
    levelId: base.levelId,
    path: base.path,
    coins: base.coins,
    commit: commit ? commit.slice(0, 7) : 'ok',
    commitFull: commit,
    url: (put.content && put.content.html_url) || '',
  } }];
}

return [{ json: {
  ok: false,
  statusCode: 502,
  error: 'GitHub PUT failed (' + status + '): ' + String((put && put.message) || 'no message'),
} }];

// Single exit for every failure path (bad input, GitHub error).
const j = $json || {};
return [{ json: {
  ok: false,
  statusCode: Number(j.statusCode || 400),
  error: String(j.error || 'unknown error'),
} }];
